import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"西溪易說卷八","description":"西溪易說 - 西溪易說卷八","frontmatter":{"title":"西溪易說卷八","description":"西溪易說 - 西溪易說卷八"},"headers":[],"relativePath":"classics/xixi/009.md","filePath":"classics/xixi/009.md"}'),i={name:"classics/xixi/009.md"};function r(c,p,_,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="西溪易說卷八" tabindex="-1">西溪易說卷八 <a class="header-anchor" href="#西溪易說卷八" aria-label="Permalink to “西溪易說卷八”">​</a></h1><p>欽定四庫全書</p><p>宋李過撰</p><p>䷣ 離下坤上 明夷，</p><p>明夷：利艱貞。彖曰：明入地中，明夷。內文明而外柔順，以蒙大難，文王以之。「利艱貞」，晦其明也。內難而能正其志，箕子以之。明出地上，明世也；明入地中，暗世也。晉變而明夷，文王之心其在是乎？夫子曰：「作易者，其有憂患乎？」其當殷之末世，文王與紂之時乎？吾獨於晉明夷見之。晉之君臣以禮相遇，交際之盛，夏、商盛時亦莫不然。有如文王之事商而不免於囚，箕子之事商而不免於狂，此非箕子、文王之所當得也，蓋至此而後可以言命。重易而至明夷，離居坤下，明不當天而入於地中，其己之所遇歟？揚雄曰：「龍以不製為龍，聖人以不平為聖人。」以文王之純德，陟降上帝，而羑里之難，固不足為文王累。以事君小心，天實臨之，而不免於疑與囚，文王豈能釋然於其心哉？故其重易也，於明夷略見一二，且婉其辭而託諸箕子。越五百歲，而夫子系易，始探其心於韋編三絕之後。於是乎作彖而明言其事，曰：內文明而外柔順，以蒙大難，文王以之。利艱貞，晦其明也。內難而能正其志，箕子以之。又作象以繫於爻辭之下，而於內卦之六二曰：「六二之吉，順以則也。」蓋文王至是而昭昭矣。夫子曰：「文王既沒，文不在茲乎？」信乎其神交而精契也。就六爻觀之，外卦則箕子用之，內卦則文王用之。卦辭「利艱貞」，文王為箕子發也。蓋內難而能正其志，箕子之事也。爻既言之矣，使彖不言文王之事，孰知夫內明外順以蒙大難之為文王事耶？然夫子既明言之，二千年來談易者未有得其心者。噫！聖賢契合，固如是之難也哉！</p><p>象曰：明入地中，明夷，君子以蒞眾，用晦而明。日入於地，明夷之象也。晦其明以蒞眾，處明夷之世之道也。君子處亂世，惟其有平治天下之志，故遵養於其間而不為苟去，外雖用晦，而中蓋甚明也。</p><p>初九，明夷于飛，垂其翼；君子於行，三日不食。有攸往，主人有言。象曰：「君子於行」，義不食也。</p><p>內卦，文王事。初爻言其被囚而去也。當「明夷」之時，飛而垂翼，縲其手也。「君子於行」，受縶而去也。「三日不食」，受患之至也。聖人處患難，何憂哉？親之過大而不怨，是愈疏也。「主人有言」，君有疑言。象曰：義不食也。以君臣之義言之，故當不食也。</p><p>六二：明夷於左股，用拯馬壯，吉。象曰：六二之「吉」，順以則也。</p><p>二，言其在羑里也。傷及其股，謂其足梏而不得行也。「用拯馬壯吉」，聖人已有知患難之理。方其在難也，人以為難，而聖人已拯壯馬以出，知時之不能害己也。象曰：「順以則也」。此看得夫子盡見文王之心。聖人舉措純乎天理。文王之出患難，自循夫理之外，不容一毫私意。詩曰：「帝謂文王，不大聲以色，不長夏以革。不識不知，順帝之則。」文王純乎順帝則也。其出羑里，用此道也。司馬遷作史記，乃謂閎、散輩以計出文王。如此立言，其得罪於聖人也不可贖。</p><p>九三：明夷於南狩，得其大首，不可疾，貞。象曰：「南狩」之志，乃大得也。</p><p>三言其出羑里，受命為西伯也。文王之化行於南國，故出而南狩，伐崇庸，伐密人，得其大首也。然文王征伐止此而已，所謂「三分天下有其二，以服事殷」者，其事殷之心，直不可得而瑕疵也。故文王處明夷則以「不可疾貞」；箕子處明夷則以「利艱貞」。二者各當其事可也，故曰「不可疾貞」。象曰：「乃大得也」。江漢以南，皆被文王之化，可謂「大得志也」。然文王在囚，而重爻猶未出難也，安知其南狩之事哉？曰：聖人重易，千萬世無窮之變可以逆定，況於其身而當世之事變耶！六四，入於左腹，獲明夷之心，於出門庭。象曰：「入於左腹」，獲心意也。</p><p>外卦箕子用之，此言其徉狂時也。「入於左腹」，狂左道也。入於紂腹，於是得紂之心意，乃出紂之門庭，而紂不加罪，故曰「於出門庭」。象曰：「獲心意也」，言得紂之心意也。當是時，微子不免於行道，比干不免於焚炙，而箕子獨以奴免，非「入於左腹」，安可得也！</p><p>六五，箕子之明夷，利貞。象曰：箕子之貞，明不可息也。五言箕子之能正其志也。卦辭「利艱貞」，全屬箕子。艱者，難也；貞者，正也。言箕子處內難而其志則正也。故於此曰「箕子之明夷，利貞」，謂如箕子之處明夷，志正則宜也。象曰：「明不可息也」，言箕子之明處未嘗息也。武王興，縲囚釋而洪範作，彝倫九疇絕而復續，非晦於昔而明於今也，天理本未嘗息也。</p><p>上六：不明晦，初登於天，後入於地。象曰：「初登於天」，照四國也。「後入於地」，失則也。此言紂也。「不明晦」，言明入地中，不明而晦也。始亦正位，故「初登於天」；後失君道，故「後入於地」。象曰：「初登於天」，照四國也。後入於地，失則也。理之至當而不可過為則，君自有君之則。紂失君道，故曰失則。</p><p>看。明夷卦每謂文王之心，千載而上惟夫子知之，千載而下惟韓子知之。箕子之志，千載而上惟夫子知之，千載而下，惟柳子知之。韓文公羑里操曰：「目閃閃兮其凝其盲，耳蕭蕭兮聽不聲聞。朝不見日出兮，夜不見月與星。有知無知兮，為死為生。臣罪當誅兮，天王聖明。」可謂得文王之心。柳子厚作箕子廟碑有云：「當是時，周時未至，商祀未殄，微子已去，比干已死。向使紂惡未稔而先斃，武庚念亂以圖存，國無其人，誰與共理？此則人事之或然者也。先生隱忍而就此，其亦有志於斯乎？」可謂見得箕子之心。䷤ 離下巽上 家人，</p><p>家人：利女貞。彖曰：家人，女正位乎內，男正位乎外。男女正，天地之大義也。家人有嚴君焉，父母之謂也。父父子子，兄兄弟弟，夫夫婦婦，而家道正，正家而天下定矣。家人，正家之道也。有男女而後有夫婦，有夫婦而後有父子，有父子而後有兄弟。夫婦、父子、兄弟，人之大倫也。古人自修身齊家推之於治國平天下，莫不以此卦。九居五，男在外也。六居二，女在內也。齊家之道，莫先於正女，女正則內治，內治則外治矣，故曰「利女貞」。據彖辭，六爻皆說盡，大抵男女各有其位而不相亂也。古人治家，莫先於辨男女之位，如「內言不出於閫，外言不入於閫」之類。卦分內外，男女之位也。內卦之位女正之，外卦之位男正之。故下三爻正內之事也，上三爻正外之事也。女人之道，其始也為人女，其中也為人婦，又其終也為人母。男子之道，其始也為人子，其中也為人夫，又其終也為人父。初爻「閒有家」，為人女之道也。二爻「在中饋」，為人婦之道也。三爻「家人嗃嗃」，為人母之道也。即彖辭所謂「正位乎內」也。四爻「富家吉」，為人子之道也。五爻「假有家」，為人夫之道也。上爻上爻「威如吉」，為人父之道也。即彖辭所謂「正位乎外」也。三曰「嗃嗃」，上曰「威如」。「威如嗃嗃」，嚴貌也，父母之道也。故曰：「家人有嚴君焉，父母之謂也。」是母道亦貴乎嚴也。男女之位正，則家道正；家道正，則天下定矣。</p><p>象曰：風自火出，家人，君子以言有物而行有恆。</p><p>風自火出，橐籥之火也。大凡鼓鑄，須是鼓得許多。風從火裡出，故風自火出，橐籥自有一個戶庭閫奧，家之象也。就中必有模範。風也，火也，金也，器也，皆有模範。君子體之，言有物，行有恆。正家以身言，行，身之模範也；物，恆其則也。一身之模範，一家之模範；一家之模範，天下之模範也。</p><p>初九，閒有家，悔亡。象曰：「閒有家」，志未變也。</p><p>初言為人女之道。女子生則願為之有家，當閒之於未從人之時，則可以無後悔也，故曰「閒有家，悔亡」。象曰「志未變也」。女子從人，則志變矣。六二，無攸遂，在中饋，貞吉。象曰：六二之吉，順以巽也。二言為人婦之道。婦道不敢成事，故曰「無攸遂」；職在飲食之事，故曰「在中饋」；不與外言，故曰「貞吉」。所謂無非無儀，惟酒食是議者是也。象曰「順以巽也」，順以從夫也，所謂以順為正者也。</p><p>九三，家人嗃嗃，悔厲吉。婦子嘻嘻，終吝。象曰：「家人嗃嗃」，未失也；「婦子嘻嘻」，失家節也。</p><p>三言為人母之道也。嗃嗃，嚴肅貌。母道尚嚴，太嚴則不和，故有悔而厲。然與其狎而慢，寧若嚴而肅，故吉。若家政廢弛，婦子嘻嘻然無所恐懼，則失母道矣，故「終吝」。象曰：「嗃嗃」，未失也。謂雖母過嚴，道未失也，若嘻嘻則失節矣。</p><p>六四，富家，大吉。象曰：「富家大吉」，順在位也。</p><p>四言為人子之道，子而克家，則其家富矣，故曰「富家大吉」。象曰：順在位也。居巽體，「巽」，順也，言在子之位而能順事父母也。九五，王假有家，勿恤，吉。象曰：「王假有家」，交相愛也。五言為人夫之道，居五應二，二盡婦道，五假而有之。五君位，故曰「王假有家」。得內助則無憂矣，故曰「勿恤吉」，象曰：「交相愛也。」</p><p>上九，有孚威如，終吉。象曰：「威如」之吉，反身之謂也。上言為人父之道，父子相遇必以誠，故曰「有孚」；義方之訓必以嚴，故曰「威如」，此家道之終也。一卦六爻皆善，父子、夫婦、男女皆得其正也。一家皆正，則有終而吉矣！象曰「反身之謂也」。推原所以致吉，由修身而致也。蓋修身則家齊，家齊則國治，國治則天下平矣。卦中六爻，不惟男女之位定，剛柔之位亦不可易。上，父道也。父道貴嚴，以九居之。五，夫道也。夫道貴義，以九居之。四，子道也。子道貴順，以六居之。三，母道也。母道貴嚴，以九居之。二，婦道也。婦道貴順，以六居之。初，女子之道，安得用剛？蓋女子之未從人也，當以禮自防，不然，則為不有躬之女，故亦以九居之。六爻剛柔皆當，所以為家道之善。䷥ 兌下離上</p><p>睽，</p><p>睽：小事吉。彖曰：「睽」，火動而上，澤動而下。二女同居，其志不同行。說而麗乎明，柔進而上行，得中而應乎剛，是以「小事吉」。天地睽而其事同也，男女睽而其志通也，萬物睽而其事類也。睽之時，用火矣哉！</p><p>「睽」，離也。離與合對，天下之物不遽合也，必以離而合。聖人重卦，兌下離上，名卦以「聧」。澤性潤下，火性炎上，固相違也，取義為「睽」。然水火未嘗不相為用也，是以睽而合也。卦辭口「睽，小事吉」。當睽之時，未可遽合也。其合必以漸，故「小事吉」。彖曰：「火動而上，澤動而下」，水火之性「睽」也。二女同居，其志不同行。離與兌，二女也。女子始雖同居，終不同行，各從所適也。此聖人取「睽」之義也。然天下未有不以「睽」而合者，曰「小事吉」。蓋就卦中以二象言之，雖「睽」，以六爻言之，下三爻居說體，上三爻居明體。離以麗也，以說而麗乎明，終必合也。六五以柔居上體得中而下應九二之剛，為剛柔正應，故可以有事也。以睽之功用言之，大而天地，則日月星辰之相為紀，風雨霜露之相為教，陰陽寒暑之相為亭毒，山嶽川瀆之相為融結，莫不以睽而相合者。至於人，則男女之相求，賓主之相交，君臣之相遇，朋友之相親，莫不以「睽」而合者。微而至於物，則金木水火土之相為用，鹹酸甘苦之相為味，玄黃赤白之相為文，金石絲竹之相為節，又莫不以「睽」而成功者。故曰：「天地睽而其志同，男女睽而其志通，萬物睽而其事類。」則「睽」之一卦，思過半矣。六爻中綱領甚好。人倫有五，父子兄弟，其本同也，不以聧而合。夫婦、君臣、朋友，則以睽而合者也。故初以四言朋友之聧，二與五言君臣之睽，三與上言夫婦之睽。蓋三者不睽，則不能合也。</p><p>象曰：上火下澤，「睽」。君子以同而異。</p><p>火炎上，澤潤下，物之睽也。而水火未嘗不相為用，是以睽而同也。同而異，異而同，異同之理，惟君子能知之。</p><p>初九，悔亡。喪馬，勿逐，自復。見惡人，無咎。象曰：「見惡人」，以闢咎也。</p><p>初與四言朋友之睽，以剛應剛，朋友以義合也。同德相求，其交以誠，故曰「悔亡」。然有喪我而去者，不必逐之，聽其自復可也。蓋朋友之道，不可預為決擇，惡人之來，不可絕也，見之則無咎。孔子於孺悲、陽貨，亦為盡禮也。子夏所謂「我之不賢與，人將拒我，如之何其拒人也」？比之可者與之，不可者拒之，則狹矣。</p><p>九二，遇主於巷，無咎。象曰：「遇主於巷」，未失道也。</p><p>二五，君臣之位，故言君臣之「睽」。君臣之以「睽」而合者，非有所謂堂陛之素、半面之雅也，故曰「遇主於巷」。伊尹之莘野，太公之渭濱，諸葛孔明之草廬，皆自巷遇主也。故當事勢睽離之時，君臣相求，必欲拘堂陛之常分，則賢者無自而進矣。「遇主於巷」，處「睽」之時則然，未矢道也。六三，見輿曳，其牛掣，其人天且劓，無初有終。象曰：「見輿曳」，位不當也；「無初有終」，遇剛也。</p><p>三與上應，言夫婦之睽矣。夫婦之道，其未合之時，皆判然也，未知上為己之應也。「輿曳」「牛掣」，見其車敗也；其人髡首而劓鼻，見其人刑也。然車非真敗，人非真敗，人非真刑也，以禮自防，無因而至者，皆強暴也，故見其敗且刑。然賴乎始之「睽」，故有終之合也，故曰「無初有終」，不如是，則不有其躬矣。九四，睽孤，遇元夫，交孚，厲無咎。象曰：「交孚」「無咎」，志行也。四與初應，所以「睽」者，上不下接也。四居上體，故「睽孤」在四。以九居初，元善之夫也。四能往遇，則「交孚」而相得矣，又須嚴厲自將，則「無咎」。蓋交際之心不可不孚，而終始之義不可不敬，所謂「晏平仲善與人交，久而敬之」是也。象曰：「志行也。」「朋友以義合」，則其志同矣。</p><p>六五，悔亡。厥宗噬膚，往何咎？象曰：「厥宗噬膚」，往有慶也。五與二應，「睽」而相遇，情好款密，宜悔之亡也。二五正應，本同宗也，委巷相遇，誓言之信，不必歃牲之備也，「噬膚」可矣。古人有齧臂以相盟者，「噬膚」之謂也，然後不輕就也。義在則往，故曰「往何咎」。象曰：「往有慶也」，君臣以義合，其慶可知也。</p><p>上九，睽孤，見豕負塗，載鬼一車，先張之弧，後說之弧，匪寇婚媾，往遇雨則吉。象曰：「遇雨」之「吉」，群疑亡也。</p><p>上九，六三之夫也。當「睽」之時，其見三也，「見豕負塗」，見其行也；「載鬼一車」，見其怪也。「先張之弧」，欲與之敵也；「後說之弧」，又欲與之親也。上，「離」也；「三」，「坎」也。以「離」遇「坎」，則敵也。然上九也，六三也，以六應九，則又親也，是「匪寇」也，乃「婚媾」也。「見豕」、「見鬼」、「張弧」、「說弧」，皆妖穢乖邪之事，陰陽氛沴所致。陰陽和則無是矣，故「往遇雨則吉」。「雨」，陰陽和也。象曰：「群疑亡也。」夫婦之情合，則曏者敗刑汙怪之疑盡解矣。䷦ 艮下坎上</p><p>蹇</p><p>蹇：利西南，不利東北。利見大人，貞吉。彖曰：蹇，難也，險在前也。見險而能止，知矣哉！「蹇，利西南」，往得中也；「不利東北」，其道窮也。「利見大人」，往有功也。當位「貞吉」，以正邦也。蹇之時用大己哉！</p><p>「蹇」，滯也。何以滯？遇難而滯也。天下之為君子之學者，莫不欲得時行道，中天下而立，定四海之民，然後陰陽消長，與時偕行。君子之道，不能常通也，則遇險而正，姑退以自守，以大吾所養。天苟有平治天下之意，雷雨作而朋至，斯孚矣，此聖之所以處蹇也。卦，坎上艮下。「坎」，難也；「艮」，止也，見難而止也。曰「利西南，不利東北」，坎、艮，東北之卦也，合而成蹇，故不利東北。舍東北而西南，則蹇退矣。「利見大人」，九五也，得與五遇，則蹇道亨矣。人主，造命者也，天下之貧富貴賤，窮達亨否，皆由其軒輊，蹇所以「利見大人」也。然未可遽往也，故曰「貞吉」。彖：「蹇」，難也，險在前也，見險而能止，知矣哉！知時之不可為而止，惟如者能之。小人行險以求利，自以為知，人見其未嘗不愚也。難不在西南，故往則得中；難在東北，失道而行，宜其窮也。大人，蹇之主，謂九五有「大蹇」之志，往遇之，則有功也。卦中六久，各當其其可，君子體之，是惟無用，用則正君國定矣，故曰「以正邦也」。惟不終蹇也，則「蹇」之時用大矣哉！</p><p>象曰：山上有水，「蹇」；君子以反身修德。</p><p>山上有水，止水也。夫水之流斯為川，塞斯為淵，塞而不流，「蹇」之象也。然水居山上，其畜益大，君子觀之，反身修德以大其所養，則如萬仞之淵決，而濟物之功成矣！</p><p>初六，往蹇來譽。象曰：「往蹇來譽」，宜待也。</p><p>以柔在下，去五最遠，往而遇險必蹇，不若退而自修，以成君子之名，故曰「往蹇來譽」。象曰「宜待也」，以待時之可也。</p><p>六二，王臣蹇蹇，匪躬之故。象曰：「王臣蹇蹇」，終無尤也。五爻皆「往蹇」而來，二獨不言，而曰「王臣蹇蹇」，蓋他爻非有官守者也。二與五為正應，居王臣之位，進退不能自必也。前遇互體為二「坎」，「蹇」而又「蹇」也。處重蹇之下，遇難而死難可也。所以然者，既已委質為臣，去就不由己也，故曰「匪躬之故」。象曰「終無尤也」，謂能「匪躬」則臣節無尤矣！</p><p>九三，往蹇來反。象曰：「往蹇來反」，內喜之也。</p><p>三臨於險而居艮，得所止者也，往遇蹇則退而自反，故曰「往蹇來反」，象曰「內喜之也」，言反之得所樂也。</p><p>六四，往蹇來連。象曰：「往蹇來連」，當位實也。五非四應，往則必蹇，三善於止，不若退而連，故曰「往蹇來連」，象曰「當位實也」。三有實德，已與之連而得當也。</p><p>九五，大蹇朋來。象曰：「大蹇朋來」，以中節也。</p><p>以九五之君，正位在乾卦，則賢者雲龍風虎之會也。而處蹇之世，使在下者皆懷有不自滿之意而去，其為九五之累多矣。五有剛健中正之德，大亨天下之蹇，使之各以朋類而來，則賢者無濡滯之嘆，故曰「大蹇朋來」，象曰「以中節也」。賢者無濡滯之嘆，則得喜怒哀樂之正，故曰「中節」。</p><p>上六，往蹇來碩，吉，利見大人。象曰：「往蹇來碩」，志在內也。「利見大人」，以從貴也。</p><p>碩，大也。六往過蹇，退而得五，五已有大蹇之志矣，故曰「往蹇來碩吉。利見大人」。象曰：志在內也。上位在外，來與五遇，故曰「志在內也」。陽貴陰賤，利見九五，故曰「以從貴也」。䷧ 坎下震上</p><p>解</p><p>解：利西南，無所往，其來複，吉。有攸往，夙吉。彖曰：「解」，險以動，動而免乎險，解。「解利西南」，往得眾也；「其來複吉」，乃得中也；「有攸往，夙吉」，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲拆，解之時大矣哉！</p><p>「蹇」變而「解」，坎險居下，震動居上，動而出乎險難，解之象也。曰「利西南，無所往，其來複，吉。有攸往，夙吉」。此卦乃蹇卦之反。處蹇之時，則「利西南，無所往」而來複，則得「吉」，如「往蹇來反」之類。今「蹇」散為「解」，則向之「利西南」，無所可往而來反則得「吉」者，今可以有所往，而豫知其得吉也，故曰「有攸往，夙吉」。先儒不知卦自蹇來，反遂牽於「無所往吉」，又「有攸往吉」，故其說不定。彖曰：「解」，險以動，動而免乎險，解。「震」在坎上，動處險之外，是「動而免乎險」也。難在東北，則利在西南，宜其得眾也。「其來複吉」，乃得中也。未可往，則以來往為中也。今難既險，則往而有功矣，是以「有所往」為功也。蓋天地之理不終難也，難極則必「解」。天地未解之時，則雲雷為屯；天地既解，則雷雨作，萬物皆有發生之意矣。當君子未解難之時，天下之人在虐政膏火中，人未知有生生之所。君子既解難，則人命始有所迓續矣。故「解」之時大矣哉！</p><p>象曰：雷雨作，「解」，君子以赦過宥罪。</p><p>雲雷未成雨為屯，雷雨既作為「解」。陰陽之氣鬱結而解散則成雨，難解之象也。當難解而赦過宥罪，與之日新，則小人無所疑也。</p><p>初六：無咎。象曰：「剛柔之際，義無咎也。」</p><p>六爻二陽而四陰，當君子解小人之象，時小人尚據尊位。蓋解卦為患難方解之始，小人猶未去，君子正當用力。九二、九四當解之責，六三、六五、上六為在位小人，初六一陰居二陽之下，是自知退聽者也。小人自知退而咎之可也，蓋君子不為已甚。象曰：「剛柔之際，義無咎也。」初六一柔，本在上體，反而居下，與二陽相遇，宜其「無咎」也。</p><p>九二，田獲三狐，得黃矢，貞吉。象曰：九二「貞吉」，得中道也。二為解難之君子，「田獲三狐，得黃矢」，蓋三則為群，謂上二陰也，必盡小人之群而得之，而利器未嘗失，獲狐得矢，不遺一鏃也。以此解難，得正而吉也。象曰：「得中道也。」以二得中，故為解難之善。</p><p>六三，負且乘，致寇至，貞吝。象曰：「負且乘」，亦可醜也。自我致戎，又誰咎也。當解難之時，六陰也，猶據下卦之上，小人而乘車也，據非其所，其禍必至，故曰「負且乘，致寇至」。象曰：「負且乘」，亦可醜也。非其所據，眾所恥也。「自我致戎，又誰咎也」，禍自己致，又將誰咎？繫辭：「子曰：作易者，其知盜乎？易曰：負且乘，致寇至。」負也者，小人之事；乘也者，君子之器也。小人而乘君子之器，盜思奪之矣；上慢下暴，盜思伐之矣。慢藏誨盜，冶容誨淫。易曰：負且乘，致寇至，盜之招也。九四，解而拇，朋至斯孚。象曰：「解而拇」，未當位也。</p><p>拇最下，以九居四為解難之君子，而下應初六，猶有保祐小人之意，必解去之，則君子之朋至而相孚矣。象曰：「未當位也。」四不得中，故有此戒。</p><p>六五，君子維有解，吉。有孚於小人。象曰：「君子有解」，小人退也。</p><p>六五為「解」之主，己居君位。當「解」之時，小人猶得君而未去，然君子之解不可已也，六五何以處之？孚於小人，使之自為去就，以避賢者路可也。象曰：「君子有解，小人退也。」言君子必解難，則小人自當退也。</p><p>上六，公用射隼於高墉之上，獲之，無不利。象曰：「公用射隼」，以解悖也。</p><p>既「解」至五，而陰猶據六，是在「高墉」之象也。「公」，謂九四也，必射而獲之，然後盡解道之善，而「解」道成矣。蓋此一陰獨據高位，竊威福之權，而在己者「解」而不獲，必反為害，所謂斷蛇不殊者也。象曰：「以解悖也。」獲此一陰，則亂去矣。繫辭：「子曰：隼者，禽也；弓矢者，器也；射之者，人也。君子藏器於身，待時而動，何不利之有？」動而不括，是以出而有獲，語成器而動者也。必成器而後動，謹之至也。西溪易說卷八，</p>',68)])])}const x=a(i,[["render",r]]);export{m as __pageData,x as default};
